/** The person's grade in force on the date: the one with the latest from-date on or before it. */
function gradeOn(p: Person, date: string): string {
  let on = p.grade;
  for (const g of p.grades) if (g.from === null || g.from <= date) on = g.grade;
  return on;
}

/** A person's statements: how many, and the last one's due-total (null when n/a) and date. */
/** The figures of the sheet's descendants added up, each sheet's due-total and overdue-total as it shows them. */
interface Descendants {
  sheets: number;
  people: number;
  dueTotal: string;
  overdueTotal: string;
  /** The sheet's own figures as the store holds them now. */
  ownPeople: number;
  ownDueTotal: string;
  ownOverdueTotal: string;
  /** Per grade, the due-totals of the descendants' people on it (retired people left out), added up. */
  gradeDueTotals: Record<string, string>;
  /** Per status, how many of the descendants' claims have it. */
  statusCounts: Record<string, number>;
  /** Each descendant person's figures, with the keys of their name and aliases as names are compared. */
  personFigures: { keys: string[]; dueTotal: string | null; overdueTotal: string }[];
}

interface StatementSummary {
  personId: number;
  count: number;
  lastDueTotal: string | null;
  lastDate: string;
  /** Each statement standing, oldest first by date. */
  lines: StatementLine[];
}

/** A statement as listed: its date and due-total (null when n/a). */
      now: dates.to === '' ? this.dueTotalOf(p) : on(p, dates.to),
    }));
  });
  /** The sheet's descendants' figures, as the store held them when the sheet was loaded (as of the user's date, while one is set). */
  private readonly descendants = signal<Descendants | null>(null);
  /**
   * The sheet's own figures, as shown, and its descendants' added up. Read as of a date, every sheet of the
   * tree is as it stood at the end of that date.
   */
  protected readonly consolidated = computed(() => {
    const d = this.descendants();
    const others = d?.personFigures ?? [];
    const key = (name: string) => name.trim().toLowerCase();
    const dues = this.people().map((p) => this.dueTotalCents(p)).filter((c): c is number => c !== null)
      .concat(others.filter((o) => o.dueTotal !== null).map((o) => cents(o.dueTotal as string)));
    const overdues = [...this.overdueByPerson().values()].map((o) => o.cents)
      .concat(others.map((o) => cents(o.overdueTotal)));
    return {
      // each person once over the tree, the trim over every person's figure of the tree
      people: distinctPeople(this.people().map((p) => [key(p.name), ...p.aliases.map(key)])
        .concat(others.map((o) => o.keys))),
      dueCents: trimmedSum(dues),
      overdueCents: trimmedSum(overdues),
      grades: this.gradeSummary().map((g) => ({
        grade: g.grade,
        dueCents: cents(g.dueTotal) + cents(d?.gradeDueTotals?.[g.grade] ?? '0.00'),
      })),
      statuses: this.statusSummary().map((s) => ({ status: s.status, count: s.count + (d?.statusCounts?.[s.status] ?? 0) })),
    };
  });
  /**
   * The people a restricted user may see: the person with their name and the people of the crews that
   * person leads or belongs to, and anyone they added on this screen since the sheet was loaded; null for
   * any other role (everyone).
   */
  private readonly visibleIds = computed<ReadonlySet<number> | null>(() => {
    if (this.session.role() !== 'restricted') return null;
    const user = this.session.user()?.trim();
    const self = this.people().find((p) => p.name.trim() === user);
    const added = this.addedHere();
    if (!self) return added;
    return new Set([self.id, ...added, ...this.session.crewPeople().filter((ids) => ids.includes(self.id)).flat()]);
  });
  /** The people added on this screen since the sheet was last loaded. */
  private readonly addedHere = signal<ReadonlySet<number>>(new Set());
  /** The people on screen: everyone (a restricted user: those they may see), less the retired unless show retired is on. */
  protected readonly listed = computed(() => {
    const visible = this.visibleIds();
    const people = visible ? this.people().filter((p) => visible.has(p.id)) : this.people();
    return this.session.showRetired() ? people : people.filter((p) => !p.retired);
